class Entity < Sprite

    def initialize(x, y, image)
        super(x, y, image)
        
        self.x = x * 64 - 50
        self.y = 512 - y * 64

        self.center_x = self.image.width / 2
        self.center_y = self.image.height / 2
        self.offset_sync = true

        @dx = 0
        @dy = 0

        @bullet_image = nil
        @jump = 0
        @facing = -1
        @isGround = false
    end

    def bullet_image
        @bullet_image
      end
    def facing
        @facing
    end
    
    def hitBlock(blocks)
        self.x += @dx

        blocks.each do |block|
            if self === block
                @facing *= -1
                self.x -= @dx

                while !(self === block)
                    self.x += @dx * 0.1
                end
                self.x -= @dx * 0.5
            end
        end

        self.y += @dy
        @isGround = false
        blocks.each do |block|
            if self === block
                @jump = 0 if @dy < 0
                self.y -= @dy
                @isGround = true
                while !(self === block)
                    self.y += @dy * 0.1
                end
                self.y -= @dy * 0.1
            end
        end
    end
    def outside
        return self.y > 700 || self.x < -250
    end
end

# --- class/bullet.rb ---
"""
キャラクターが進んでいる方向に
たまをだせるようにする
"""


class Bullet < Sprite
    attr_accessor :score
  
    def initialize(x, y, chara, enemy = false)
      @facing = chara.facing
      self.x, self.y = x, y

      
      self.image = chara.bullet_image
      self.scale_x *= @facing

      @speed = 7
      @isEnemy = enemy
     
    end
  
    def update
      self.x += @facing * @speed -1
    end
    
    def isEnemy()
      return @isEnemy
    end

    def checkOutside
      return self.x < -128 || self.x > 1024 || self.y < 0 || self.y > 700
    end
    def hitBlock(blocks)
      blocks.each do |block|
        if self === block
          return true
        end
      end
      return false
    end
  
end
  



class Player < Entity

    def initialize(x, y,chara_type)

        bullet_image = Image.load_tiles('./image/bullet/player_bullet.png', 3, 1)
        case chara_type
        when 1
            image = Image.load("./image/charactor.png")
        when 2
            image = Image.load("./image/charactor2.png")
        when 3
            image = Image.load("./image/charactor3.png")
        end
        

        super(x, y, image)

        @bullet_image = bullet_image[chara_type - 1]

        @cooltime = 0
        @facing=1
        @jump = -20
        self.scale_x = 0.2
        self.scale_y = 0.2

        width = self.image.width
        height = self.image.height
        self.collision = [width * 0.2, height * 0.1, width * 0.8, height]
    end

    def move
       @dx = -1
       @dy = 0

      @dx += Input.x*5 if self.x < 1024
      @facing=Input.x if Input.x != 0
    
      if @jump == -20 && @isGround && Input.y == -1
          @jump = 21
      end

      if @jump > -20
          @jump -= 1
      end
      @dy -= @jump

      if @facing == 1
        self.scale_x = -0.2
      else
        self.scale_x = 0.2
      end  

      @cooltime -= 1
    end

    def hit(enemys)
        enemys.each do |enemy|
            if self === enemy
                return true
            end
        end
        return false
    end

    def bullet ()
        @cooltime = 20
       return Bullet.new(self.x,self.y,self)
    end
    def cooltime
        @cooltime
    end
end

