        Window.draw_scale(0, 0, backgroundImage, 1, 0.59, 0, 0)
        Window.draw_scale(60, 180, image1,0.5,0.5)
        Window.draw_scale(300, 190, image2,0.5,0.5)
        Window.draw_scale(550, 210, image3,0.5,0.5)

        #ユーザーからの入力
